sourceAssertions.sourceText:
Event_BreakingIn: {
  name: 'Breaking In',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Discard 1 <SECURE> from each Room.'],
  secondaryEffectDesc: ['Resolve a <NOISE> in each Unexplored Corridor.'],
},

Event_Damage: {
  name: 'Damage',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.'],
  primaryEffectDesc: ['Place a <MALFUNCTION> in each Room with a <ANY-INTRUDER>.'],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_DamagingFire: {
  name: 'Damaging Fire',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: [
    'Place a <MALFUNCTION> in each Room with a <FIRE>.',
    'In each Room with a <FIRE>, spread <FIRE> through Corridors with the lowest Noise value.',
  ],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_EggProtection: {
  name: 'Egg Protection',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.'],
  primaryEffectDesc: [
    'Place 2 Drones in the Nest \u2013 they immediately Attack if any <CHARACTER> is there.',
    'Place 1 Drone in each Unexplored Corridor in Section C.',
  ],
  secondaryEffectDesc: ['Each <CHARACTER> makes a Noise roll.'],
},

Event_FireBreath: {
  name: 'Fire Breath',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['In each Room with a <FIRE>, spread <FIRE> to all neighboring Rooms in Sections with an <OXYGEN-ON>.'],
  secondaryEffectDesc: ['Each <CHARACTER> makes a Noise roll.'],
},

Event_Hatching: {
  name: 'Hatching',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.'],
  primaryEffectDesc: [
    'Place a Larva in the Nest \u2013 it immediately Attack if any <CHARACTER> is there.',
    'Place 1 Larva in each Unexplored Corridor ajdacent to a <CHARACTER>.',
  ],
  secondaryEffectDesc: ['Resolve a <NOISE> in each Unexplored Corridor.'],
},

Event_LandingZoneExplodes: {
  name: 'Landing Zone Explodes',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Place a <FIRE> and a <MALFUNCTION> in the Landing Zone.'],
  secondaryEffectDesc: ['Place a <NOISE> in each Unexplored Corridor without a <NOISE>.'],
},

Event_LifeSupportFailure: {
  name: 'Life Support Failure',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Flip all <OXYGEN-ON> to <OXYGEN-OFF>. Place a <MALFUNCTION> in each Life Support Control Room.'],
  secondaryEffectDesc: ['Place a <NOISE> in each Unexplored Corridor without a <NOISE>.'],
},

Event_NoWayOut: {
  name: 'No Way Out',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Place 4 Adults in each non-Reinforced Corridor adjacent to the Landing Zone.'],
  secondaryEffectDesc: ['Each <CHARACTER> makes a Noise roll.'],
},

Event_OverwhelmingEnemies: {
  name: 'Overwhelming Enemies',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Place 1 Drone in each Corridor with a <NOISE> adjacent to a <CHARACTER>.'],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_Panic: {
  name: 'Panic',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: [
    'Each <CHARACTER> in a Room with an <ANY-INTRUDER> or adjacent to a Corridor with an <ANY-INTRUDER>:',
    'Loses 1 <OXYGEN> or spends <AMMO>.',
  ],
  secondaryEffectDesc: ['Resolve a <NOISE> in each Unexplored Corridor.'],
},

Event_ProtectServe: {
  name: 'Protect & Serve',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: [
    'Place 2 Drones in the Room/Corridor with the Queen \u2013 they do not Attack.',
    'If there is no Queen on the map, add 2 random Drone tokens to the bag.',
  ],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_ReactorOverheating: {
  name: 'Reactor Overheating',
  intrudersEffectDesc: [
    'All <ANY-INTRUDER> in each <CORRIDOR-GRAVE>, <CORRIDOR-HOR> and <CORRIDOR-ACUTE>.',
    'Then, all <ANY-INTRUDER> in every Room move.',
  ],
  primaryEffectDesc: [
    'If a <MALFUNCTION> is in the Cooling System Room or the Reactor Room, Activate the Autodestruction Procedure.',
    'Then, place a <MALFUNCTION> in each of these Rooms.',
  ],
  secondaryEffectDesc: ['Reshuffle the Event deck.'],
},

Event_RiseOfTheMachine: {
  name: 'Rise Of The Machine',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: [
    'Place a <MALFUNCTION> on the <ROBOT>.',
    'Place a <MALFUNCTION> in a Room with the <ROBOT>.',
    'Each <CHARACTER> in that Room loses 2 <HP>.',
  ],
  secondaryEffectDesc: ['Place a <NOISE> in each Unexplored Corridor without a <NOISE>.'],
},

Event_ScentOfPrey: {
  name: 'Scent Of Prey',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Resolve each <NOISE> adjacent to a <CHARACTER>.'],
  secondaryEffectDesc: ['Each <CHARACTER> makes a Noise roll.'],
},

Event_ShortCircuit: {
  name: 'Short Circuit',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-GRAVE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['In Sections with an <OXYGEN-ON>:', 'Place a <FIRE> in each Room with a <MALFUNCTION>.'],
  secondaryEffectDesc: ['Each <CHARACTER> in a Room without a <SECURE> resolves <HAZARD>.'],
},

Event_SystemFailure: {
  name: 'System Failure',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-HOR> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['Place a <MALFUNCTION> in each <COMPUTER> Room.'],
  secondaryEffectDesc: ['Resolve a <NOISE> in each Unexplored Corridor.'],
},

Event_TheQueenAwakens: {
  name: 'The Queen Awakens',
  intrudersEffectDesc: ['All <ANY-INTRUDER> in each <CORRIDOR-ACUTE> move.', 'Then, all <ANY-INTRUDER> in every Room move.'],
  primaryEffectDesc: ['If the Queen is alive, add all Queen tokens to the bag.'],
  secondaryEffectDesc: ['Place a <NOISE> in each Unexplored Corridor without a <NOISE>.'],
},

ExplorationRobot: {
  name: 'Exploration Robot',
  desc: [
    'Move the <ROBOT> up to 2 times.',
    'Move the <ROBOT> through an Unexplored Corridor and resolve an Exploration Sequence. Do not resolve the Entrance effect.',
  ],
  color: 'yellow',
},

MedicalRobot: {
  name: 'Medical Robot',
  desc: [
    'Move the <ROBOT> up to 2 times.',
    'A <CHARACTER> of your choice in a Room with the <ROBOT> discards 1 Serious Wound or restores 2<HP>.',
  ],
  color: 'green',
},

MilitaryRobot: {
  name: 'Military Robot',
  desc: [
    'Move the <ROBOT> once.',
    'Choose a Corridor adjacent to the <ROBOT> and roll a Burst die. Deal Hits equal to the result in that Corridor.\n<DICE-BURST>: Place a <MALFUNCTION> on the <ROBOT>',
  ],
  color: 'red',
},

SecuringRobot: {
  name: 'Securing Robot',
  desc: [
    'Move the <ROBOT> up to 3 times.',
    'Open or Close 1 Door accessible to the <ROBOT>.',
    'Place 2 <SECURE> in a Room with the <ROBOT>.',
  ],
  color: 'other',
},

ServerRobot: {
  name: 'Server Robot',
  desc: [
    'Move the <ROBOT> up to 3 times.',
    'If the <ROBOT> is in a <COMPUTER> Room, use the Room (even with a <MALFUNCTION>).',
  ],
  color: 'other',
},

TechnicalRobot: {
  name: 'Technical Robot',
  desc: ['Move the <ROBOT> up to 2 times.', 'Discard a <MALFUNCTION> or a <FIRE> from the Room with the <ROBOT>.'],
  color: 'yellow',
},
